from pathlib import Path
import json,math
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
r=Path('results');training=json.loads((r/'training.json').read_text());planning=json.loads((r/'planning-lite.json').read_text());metrics=training['prediction'];fig,ax=plt.subplots(figsize=(6.5,3.2));x=[m['horizon'] for m in metrics];ax.plot(x,[m['latent_mse_mean'] for m in metrics],'-o',color='#8161ae',label='Learned recurrent dynamics');ax.plot(x,[m['constant_state_mse'] for m in metrics],'-o',color='#91a27f',label='Constant-state baseline');ax.set(xlabel='Prediction horizon (actions)',ylabel='Held-out latent MSE',xticks=x);ax.spines[['top','right']].set_visible(False);ax.legend(frameon=False);ax.grid(alpha=.12);fig.tight_layout();fig.savefig(r/'prediction.png',dpi=160);plt.close(fig)
lines=['# Measured release results','',f"Training seed: 714. Dataset: {training['dataset']['episodes']} episodes × {training['dataset']['steps']} actions, split by whole episode. True contact fraction: {training['dataset']['contactFraction']:.1%}; movement fraction: {training['dataset']['movingFraction']:.1%}.",'','Representation training: '+', '.join(training['representation_training'])+'.','',f"Training/export elapsed {training['elapsed_seconds']:.1f} seconds on the local CPU; this is an observed run time, not a hardware-independent promise.",'','## Prediction on held-out episodes','','| Horizon | Latent MSE ± SD | Static MSE | Decoded xy error (units) | Angle error (rad) |','|---:|---:|---:|---:|---:|']
for m in metrics:lines.append(f"| {m['horizon']} | {m['latent_mse_mean']:.4f} ± {m['latent_mse_std']:.4f} | {m['constant_state_mse']:.4f} | {m['position_mean_units']:.3f} | {m['orientation_mean_radians']:.3f} |")
lines+=['','## Planning benchmark','',planning['backend'], '',f"{planning['seeds']} reserved seeds per difficulty, {planning['budget']} actions per task, same seeds for both methods. Success: ≥95% coverage for three consecutive actions. No privileged planner inputs.",'','| Difficulty | Method | Success | Mean final coverage | Mean planning latency |','|---|---|---:|---:|---:|']
summary={}
for diff in ['easy','medium','challenge']:
 for method in ['random','latent-mpc']:
  rows=[x for x in planning['rows'] if x['difficulty']==diff and x['method']==method];success=sum(x['success'] for x in rows);rate=success/len(rows);summary[diff,method]=rate;lines.append(f"| {diff} | {method} | {success}/{len(rows)} ({rate:.0%}) | {np.mean([x['finalCoverage'] for x in rows]):.1%} | {np.mean([x['latencyMean'] for x in rows]):.2f} ms |")
passed=summary['easy','latent-mpc']>=.5 and summary['easy','latent-mpc']>=2*summary['easy','random'];lines+=['',f"**Reliability gate: {'PASS' if passed else 'NOT MET — experimental'}**. The gate does not change the reported outcomes. A visually useful push is not counted as task success.",'','Browser viewport results are in `browser.json`. Portrait/landscape use touch emulation, not a physical Android device. Node WASM timing is not a phone benchmark.','', 'Failure labels are coarse descriptive categories derived from actual contact and achieved coverage. They do not prove the causal reason for each failure.','', 'The original hard-mask/pose-supervised development experiment missed all 50 easy goals; its negative result is retained in `experiment-v1`. Hyperparameter and representation changes used development seeds; the final benchmark uses separately reserved seeds.']
(r/'RESULTS.md').write_text('\n'.join(lines)+'\n');print('\n'.join(lines))
